<script setup>
import {ref,onMounted} from 'vue'
import {ShieldCheck,Send,LoaderCircle} from 'lucide-vue-next'
import {api,auth,date} from '../api'
import ProfileContactEditor from './ProfileContactEditor.vue'
import RegistrationProof from './RegistrationProof.vue'
const props=defineProps({hasProof:Boolean}),emit=defineEmits(['updated'])
const profile=ref(null),requesting=ref(false),busy=ref(false),error=ref(''),done=ref(false)
const form=ref({name:'',level:1,job:'',reason:''})
async function load(){try{profile.value=await api('/profile');if(profile.value.characters[0])Object.assign(form.value,{name:profile.value.characters[0].name,level:profile.value.characters[0].level,job:profile.value.characters[0].job})}catch(e){error.value=e.message}}
async function submit(){busy.value=true;error.value='';try{await api('/profile/character-request',{method:'POST',data:form.value});requesting.value=false;done.value=true;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="profile-panel"><div class="profile-account-line"><span>登录账号</span><strong>{{auth.user?.username}}</strong></div><ProfileContactEditor @saved="emit('updated')"/><section class="profile-role-section"><div class="profile-section-heading"><div><h3><ShieldCheck :size="18"/>角色资料</h3><p>仅管理员可修改，发布时自动带入已保存的角色信息。</p></div><span class="tag">管理员维护</span></div><template v-if="profile"><div v-for="c in profile.characters" :key="c.id" class="profile-character"><strong>{{c.name}}</strong><span>Lv.{{c.level}} · {{c.job||'未填写职业'}}</span></div><RegistrationProof v-if="hasProof" :user-id="auth.user.id"/><p v-if="!profile.characters.length" class="hint">暂无角色资料，请联系管理员补充。</p><button v-if="!requesting&&!profile.character_requests.some(r=>r.status==='pending')" class="button" @click="requesting=true"><Send :size="15"/>联系管理员修改</button><form v-if="requesting" class="stack profile-request-form" @submit.prevent="submit"><div class="form-grid"><label>正确的游戏 ID<input v-model="form.name" maxlength="40" required></label><label>正确的等级<input v-model.number="form.level" type="number" min="1" max="300" required></label></div><label>职业<input v-model="form.job" maxlength="30"></label><label>修改原因<textarea v-model="form.reason" rows="2" minlength="3" maxlength="350" required placeholder="说明需要更正的内容，管理员核实后修改"></textarea></label><div class="button-row"><button class="button primary" :disabled="busy"><LoaderCircle v-if="busy" :size="15" class="spin"/>提交管理员审核</button><button class="button" type="button" @click="requesting=false">取消</button></div></form><p v-if="done" class="profile-success" role="status">已发给管理员，审核前角色资料保持原样。</p><div v-for="r in profile.character_requests" :key="r.id" class="profile-request-status"><span>{{r.status==='pending'?'等待管理员处理':r.status==='resolved'?'管理员已处理':'申请未通过'}}</span><small>{{date(r.created_at)}}</small><p v-if="r.decision">{{r.decision}}</p></div></template></section><p v-if="error" class="error" role="alert">{{error}}</p></div></template>
